effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    vec2 px = uv * acResolution;
    float a = radians(angleDeg);
    mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
    vec2 cell = R * px / cellSize;
    vec2 cellId = floor(cell);
    vec2 center = (cellId + 0.5) * cellSize;
    vec2 centerUV = (transpose(R) * center) / acResolution;

    vec4 sampled = texture(inputImg, centerUV);
    float L = dot(sampled.rgb, vec3(0.2126, 0.7152, 0.0722));
    float t = clamp((1.0 - L) * contrast, 0.0, 1.0);
    float radius = sqrt(t) * (cellSize * 0.5);

    vec2 local = R * px - center;
    float d = length(local);
    float aa = fwidth(d) * 0.5 + 0.5;
    float dotMask = 1.0 - smoothstep(radius - aa, radius + aa, d);

    vec3 col = mix(bgColor.rgb, dotColor.rgb, dotMask);
    fragColor = vec4(col, sampled.a);
}
